arguments.command:
cd /tmp/sv-faa7863734d14ea683fb893dfdd791c9

# Try using nm on the debug file to find symbols at those addresses
# Or use objdump --syms. Let's use readelf which is architecture-independent for symbol tables
# Extract symbol table and find matching addresses

# All PC addresses to resolve:
ADDRS="0x222098 0x2241ac 0x1abc80 0x16de04 0x2f4b20 0x2f4c84 0x2c1a40"

# Use readelf to dump the symbol table, then match addresses
readelf -sW libmonosgen-2.0.so.debug | awk '
BEGIN { 
    split("0x222098 0x2241ac 0x1abc80 0x16de04 0x2f4b20 0x2f4c84 0x2c1a40", targets)
    for (i in targets) { 
        t = strtonum(targets[i])
        target_addrs[t] = targets[i]
    }
}
/FUNC/ {
    addr = strtonum("0x" $2)
    size = strtonum($3)
    name = $8
    if (addr > 0 && size > 0) {
        for (t in target_addrs) {
            if (t >= addr && t < addr + size) {
                offset = t - addr
                printf "%s -> %s+0x%x\n", target_addrs[t], name, offset
                delete target_addrs[t]
            }
        }
    }
}
END {
    for (t in target_addrs) {
        printf "%s -> (not found)\n", target_addrs[t]
    }
}' | sort

