# Try with larger size limit for the remaining addresses
for addr in 0x2f4b20 0x2f4c84; do
    dec_addr=$((addr))
    result=$(awk -v target="$dec_addr" '
    {
        a = strtonum("0x" $1)
        s = strtonum($2)
        if (a <= target && target < a + s) {
            printf "%s (size=%d) +0x%x\n", $3, s, target - a
        }
    }' /tmp/syms.txt)
    echo "$addr -> $result"
done", "description": "Resolve remaining addresses"}

