cd /tmp/sv-faa7863734d14ea683fb893dfdd791c9

# These addresses are in the .bss/.data section, not code. Let me check which section they're in
readelf -S libmonosgen-2.0.so.debug | grep -E "^\s+\[" | awk '{
    if (NF > 5) {
        name=$2; addr=strtonum("0x"$4); size=strtonum("0x"$6); 
        if (addr <= 0x2f4b20 && 0x2f4b20 < addr+size) printf "0x2f4b20 is in section %s (addr=0x%x size=0x%x)\n", name, addr, size
    }
}'

# Actually wait - these are PC (program counter) values so they must be in .text
# Let me check the .text section range
readelf -SW libmonosgen-2.0.so.debug | grep '\.text'

